files.run-native.sh:
#!/usr/bin/env bash
set -u
ROOT=$PWD
export FM_VALIDATION_EVIDENCE=/Users/charlesabrooker/.no-mistakes/evidence/01M4YHMB6HGEVT2W2166E3PQYW
python3() {
  command python3 "$@"
  local status=$?
  if [ "$status" -eq 0 ] && [ "${2:-}" = "$ROOT/tests/fm-jev-guard-native-assert.py" ]; then
    command python3 -I "$ROOT/.test-validation/collect-native.py" "$3" "$4" "$5" "$6" "$FM_VALIDATION_EVIDENCE" || return $?
  fi
  return "$status"
}
case "${1:-}" in
  omp) export FM_JEV_GUARD_OMP_LIVE=1; . "$ROOT/tests/fm-jev-guard-omp-live-e2e.test.sh" ;;
  claude) export FM_JEV_GUARD_CLAUDE_LIVE=1; . "$ROOT/tests/fm-jev-guard-claude-live-e2e.test.sh" ;;
  *) exit 2 ;;
esac
